from django import forms
from .models import Quarto

class QuartoForm(forms.ModelForm):
    class Meta:
        model = Quarto
        fields = ['numero', 'tipo', 'disponivel']

    def clean_numero(self):
        numero = self.cleaned_data['numero']
        if numero < 1:
            raise forms.ValidationError('O número deve ser maior que zero.')
        return numero

from django.shortcuts import get_object_or_404, redirect, render
from .forms import QuartoForm
from .models import Quarto

def lista_quartos(request):
    quartos = Quarto.objects.filter(disponivel=True).order_by('numero')
    return render(request, 'quartos/lista.html', {'quartos': quartos})

def detalhe_quarto(request, pk):
    quarto = get_object_or_404(Quarto, pk=pk)
    return render(request, 'quartos/detalhe.html', {'quarto': quarto})

def criar_quarto(request):
    form = QuartoForm(request.POST if request.method == 'POST' else None)
    if request.method == 'POST' and form.is_valid():
        form.save()
        return redirect('quartos:lista')
    return render(request, 'quartos/form.html', {'form': form})

from rest_framework import serializers, viewsets
from .models import Quarto

class QuartoSerializer(serializers.ModelSerializer):
    class Meta:
        model = Quarto
        fields = ['id', 'numero', 'tipo', 'disponivel']

class QuartoViewSet(viewsets.ModelViewSet):
    queryset = Quarto.objects.all().order_by('numero')
    serializer_class = QuartoSerializer

import pytest
from django.urls import reverse
from quartos.models import Quarto

@pytest.mark.django_db
def test_model():
    quarto = Quarto.objects.create(numero=101, tipo='Standard')
    assert str(quarto) == 'Quarto 101 — Standard'

@pytest.mark.django_db
def test_view_lista(client):
    Quarto.objects.create(numero=102, tipo='Luxo', disponivel=True)
    response = client.get(reverse('quartos:lista'))
    assert response.status_code == 200
    assert b'Luxo' in response.content

@pytest.mark.django_db
def test_api_post(client):
    response = client.post('/api/quartos/', data='{"numero": 103, "tipo": "Suite", "disponivel": true}', content_type='application/json')
    assert response.status_code == 201
    assert response.json()['numero'] == 103
    assert Quarto.objects.filter(numero=103).exists()
